"""
红黑树增强版 - 高级功能合集
================================
1. 可视化树形打印
2. 验证红黑树五大性质
3. 前驱 / 后继查找
4. 第K小 / 第K大元素（带子树大小）
5. 区间查询：范围内的所有元素
6. 从有序数组批量构建平衡红黑树
7. 求树的最大深度与黑高度
"""


class RBNode:
    """红黑树节点"""
    def __init__(self, key, color='RED'):
        self.key = key
        self.color = color
        self.left = None
        self.right = None
        self.parent = None
        self.size = 1


class RedBlackTreeAdvanced:
    """红黑树增强版"""

    def __init__(self):
        self.NIL = RBNode(key=None, color='BLACK')
        self.root = self.NIL

    # ====================== 基础操作 ======================

    def _update_size(self, node):
        if node and node != self.NIL:
            node.size = node.left.size + node.right.size + 1

    def _left_rotate(self, x):
        y = x.right
        x.right = y.left
        if y.left != self.NIL:
            y.left.parent = x
        y.parent = x.parent
        if x.parent is None:
            self.root = y
        elif x == x.parent.left:
            x.parent.left = y
        else:
            x.parent.right = y
        y.left = x
        x.parent = y
        self._update_size(x)
        self._update_size(y)

    def _right_rotate(self, y):
        x = y.left
        y.left = x.right
        if x.right != self.NIL:
            x.right.parent = y
        x.parent = y.parent
        if y.parent is None:
            self.root = x
        elif y == y.parent.right:
            y.parent.right = x
        else:
            y.parent.left = x
        x.right = y
        y.parent = x
        self._update_size(y)
        self._update_size(x)

    def insert(self, key):
        node = RBNode(key)
        node.left = self.NIL
        node.right = self.NIL
        y = None
        x = self.root
        while x != self.NIL:
            y = x
            y.size += 1
            x = x.left if key < x.key else x.right
        node.parent = y
        if y is None:
            self.root = node
        elif key < y.key:
            y.left = node
        else:
            y.right = node
        self._fix_insert(node)

    def _fix_insert(self, k):
        while k != self.root and k.parent.color == 'RED':
            if k.parent == k.parent.parent.left:
                uncle = k.parent.parent.right
                if uncle.color == 'RED':
                    uncle.color = 'BLACK'
                    k.parent.color = 'BLACK'
                    k.parent.parent.color = 'RED'
                    k = k.parent.parent
                else:
                    if k == k.parent.right:
                        k = k.parent
                        self._left_rotate(k)
                    k.parent.color = 'BLACK'
                    k.parent.parent.color = 'RED'
                    self._right_rotate(k.parent.parent)
            else:
                uncle = k.parent.parent.left
                if uncle.color == 'RED':
                    uncle.color = 'BLACK'
                    k.parent.color = 'BLACK'
                    k.parent.parent.color = 'RED'
                    k = k.parent.parent
                else:
                    if k == k.parent.left:
                        k = k.parent
                        self._right_rotate(k)
                    k.parent.color = 'BLACK'
                    k.parent.parent.color = 'RED'
                    self._left_rotate(k.parent.parent)
        self.root.color = 'BLACK'

    def search(self, key):
        node = self.root
        while node != self.NIL:
            if key == node.key:
                return node
            node = node.left if key < node.key else node.right
        return None

    def inorder(self):
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node, result):
        if node != self.NIL:
            self._inorder(node.left, result)
            result.append(node.key)
            self._inorder(node.right, result)

    # ====================== 1. 可视化树形打印 ======================

    def visualize(self):
        """树形可视化打印"""
        if self.root == self.NIL:
            print("  (空树)")
            return
        lines = []
        self._visualize_node(self.root, "", True, lines)
        for line in lines:
            print(line)

    def _visualize_node(self, node, prefix, is_last, lines):
        if node == self.NIL:
            return
        tag = "---BLACK" if node.color == 'BLACK' else "---RED"
        lines.append(prefix + ("└── " if is_last else "├── ") + str(node.key) + tag)
        new_prefix = prefix + ("    " if is_last else "│   ")
        children = []
        if node.left != self.NIL:
            children.append(('L', node.left))
        if node.right != self.NIL:
            children.append(('R', node.right))
        for i, (direction, child) in enumerate(children):
            self._visualize_node(child, new_prefix, i == len(children) - 1, lines)

    # ====================== 2. 验证红黑树五大性质 ======================

    def verify(self):
        """验证红黑树五大性质，返回 (通过, 原因列表)"""
        errors = []
        if self.root == self.NIL:
            return True, []
        # 性质2: 根节点是黑色
        if self.root.color != 'BLACK':
            errors.append("性质2违反: 根节点不是黑色")
        # 性质4: 红色节点的子节点必须是黑色
        self._check_red_property(self.root, errors)
        # 性质5: 所有路径黑高相同
        black_height = self._check_black_height(self.root, 0, errors)
        return len(errors) == 0, errors

    def _check_red_property(self, node, errors):
        if node == self.NIL:
            return
        if node.color == 'RED':
            if node.left.color == 'RED':
                errors.append(f"性质4违反: 红色节点{node.key}的左子节点{node.left.key}也是红色")
            if node.right.color == 'RED':
                errors.append(f"性质4违反: 红色节点{node.key}的右子节点{node.right.key}也是红色")
        self._check_red_property(node.left, errors)
        self._check_red_property(node.right, errors)

    def _check_black_height(self, node, current_bh, errors):
        if node == self.NIL:
            return current_bh + 1
        if node.color == 'BLACK':
            current_bh += 1
        left_bh = self._check_black_height(node.left, current_bh, errors)
        right_bh = self._check_black_height(node.right, current_bh, errors)
        if left_bh != right_bh:
            errors.append(f"性质5违反: 节点{node.key}左黑高{left_bh} != 右黑高{right_bh}")
        return left_bh

    # ====================== 3. 前驱 / 后继查找 ======================

    def minimum(self, node=None):
        """子树最小节点"""
        if node is None:
            node = self.root
        while node.left != self.NIL:
            node = node.left
        return node

    def maximum(self, node=None):
        """子树最大节点"""
        if node is None:
            node = self.root
        while node.right != self.NIL:
            node = node.right
        return node

    def predecessor(self, key):
        """前驱：小于key的最大值"""
        node = self.root
        pred = None
        while node != self.NIL:
            if key > node.key:
                pred = node
                node = node.right
            else:
                node = node.left
        return pred.key if pred else None

    def successor(self, key):
        """后继：大于key的最小值"""
        node = self.root
        succ = None
        while node != self.NIL:
            if key < node.key:
                succ = node
                node = node.left
            else:
                node = node.right
        return succ.key if succ else None

    # ====================== 4. 第K小 / 第K大 ======================

    def kth_smallest(self, k):
        """第K小元素 (k从1开始)"""
        node = self.root
        while node != self.NIL:
            left_size = node.left.size
            if k == left_size + 1:
                return node.key
            elif k <= left_size:
                node = node.left
            else:
                k -= left_size + 1
                node = node.right
        return None

    def kth_largest(self, k):
        """第K大元素 (k从1开始)"""
        return self.kth_smallest(self.root.size - k + 1)

    # ====================== 5. 区间查询 ======================

    def range_query(self, low, high):
        """返回 [low, high] 范围内的所有元素"""
        result = []
        self._range_collect(self.root, low, high, result)
        return result

    def _range_collect(self, node, low, high, result):
        if node == self.NIL:
            return
        if node.key > low:
            self._range_collect(node.left, low, high, result)
        if low <= node.key <= high:
            result.append(node.key)
        if node.key < high:
            self._range_collect(node.right, low, high, result)

    # ====================== 6. 从有序数组批量构建 ======================

    @classmethod
    def from_sorted_array(cls, arr):
        """从有序数组批量构建平衡红黑树 O(n)"""
        tree = cls()
        tree.root = tree._build_balanced(arr, 0, len(arr) - 1, None)
        return tree

    def _build_balanced(self, arr, lo, hi, parent):
        if lo > hi:
            return self.NIL
        mid = (lo + hi) // 2
        node = RBNode(arr[mid], color='BLACK')
        node.parent = parent
        node.left = self._build_balanced(arr, lo, mid - 1, node)
        node.right = self._build_balanced(arr, mid + 1, hi, node)
        node.size = node.left.size + node.right.size + 1
        return node

    # ====================== 7. 最大深度 & 黑高度 ======================

    def max_depth(self):
        """树的最大深度"""
        return self._depth(self.root)

    def _depth(self, node):
        if node == self.NIL:
            return 0
        return 1 + max(self._depth(node.left), self._depth(node.right))

    def black_height(self):
        """根到任意叶子的黑节点数"""
        if self.root == self.NIL:
            return 0
        count = 0
        node = self.root
        while node != self.NIL:
            if node.color == 'BLACK':
                count += 1
            node = node.left
        return count

    # ====================== 辅助：元素个数 ======================

    def __len__(self):
        return self.root.size if self.root != self.NIL else 0


